    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 1. Authentication & Roles\nenum Role {\n  Admin\n  Cashier\n  Waiter\n  KitchenStaff\n}\n\nmodel User {\n  id        Int      @id @default(autoincrement())\n  name      String\n  email     String   @unique\n  password  String\n  role      Role     @default(Cashier)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  sessions Session[]\n  orders   Order[]   @relation(\"OrderWaiter\")\n  cart     Cart[]\n}\n\nmodel Otp {\n  id        Int      @id @default(autoincrement())\n  email     String\n  otp       String\n  status    Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 2. Menu Management\nmodel FoodCategory {\n  id        Int      @id @default(autoincrement())\n  name      String\n  image     String?\n  status    Boolean  @default(true) // Available/Unavailable\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  foods Food[]\n\n  @@map(\"foodcategory\")\n}\n\nmodel Food {\n  id                 Int      @id @default(autoincrement())\n  name               String\n  description        String?\n  price              Decimal  @db.Decimal(10, 2)\n  discountPercentage Decimal  @default(0) @db.Decimal(5, 2) // Item-specific discount\n  image              String?\n  categoryId         Int\n  status             Boolean  @default(true) // Available/Out of Stock\n  ingredients        String? // Simple string list for now, or JSON\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  // Relations\n  category   FoodCategory @relation(fields: [categoryId], references: [id])\n  orderItems OrderItem[]\n  cart       Cart[]\n\n  @@map(\"Food\")\n}\n\n// 3. Order Management\nenum OrderStatus {\n  New\n  InProgress\n  Ready\n  Served\n  Paid\n  Cancelled\n}\n\nenum OrderType {\n  DineIn\n  Takeaway\n}\n\nmodel Order {\n  id          Int         @id @default(autoincrement())\n  orderNumber String      @unique @default(uuid()) // Or a generated daily sequence\n  type        OrderType\n  status      OrderStatus @default(New)\n\n  // Dine-in fields\n  tableNumber String?\n\n  // Takeaway fields\n  customerName  String?\n  customerPhone String?\n\n  // Financials\n  totalAmount Decimal @default(0) @db.Decimal(10, 2)\n\n  // Tracking\n  waiterId  Int? // Who took the order\n  sessionId Int? // Which POS session\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  waiter     User?       @relation(\"OrderWaiter\", fields: [waiterId], references: [id])\n  session    Session?    @relation(fields: [sessionId], references: [id])\n  items      OrderItem[]\n  bill       Bill?\n  customer   Customer?   @relation(fields: [customerId], references: [id])\n  customerId Int?\n}\n\nmodel OrderItem {\n  id        Int     @id @default(autoincrement())\n  orderId   Int\n  foodId    Int\n  quantity  Int\n  unitPrice Decimal @db.Decimal(10, 2)\n  subtotal  Decimal @db.Decimal(10, 2)\n  notes     String? // Special instructions\n\n  // Relations\n  order Order @relation(fields: [orderId], references: [id])\n  food  Food  @relation(fields: [foodId], references: [id])\n}\n\n// 4. Billing & Checkout\nenum PaymentMethod {\n  Cash\n  Card\n  Mobile\n  Split\n}\n\nmodel Bill {\n  id            Int    @id @default(autoincrement())\n  orderId       Int    @unique\n  invoiceNumber String @unique\n\n  subtotal   Decimal @db.Decimal(10, 2)\n  tax        Decimal @default(0) @db.Decimal(10, 2)\n  discount   Decimal @default(0) @db.Decimal(10, 2)\n  grandTotal Decimal @db.Decimal(10, 2)\n\n  paymentMethod PaymentMethod?\n  isPaid        Boolean        @default(false)\n\n  createdAt DateTime @default(now())\n\n  // Relations\n  order        Order         @relation(fields: [orderId], references: [id])\n  transactions Transaction[]\n}\n\nmodel Transaction {\n  id        Int           @id @default(autoincrement())\n  billId    Int\n  amount    Decimal       @db.Decimal(10, 2)\n  method    PaymentMethod\n  reference String? // Trans ID for cards etc.\n  createdAt DateTime      @default(now())\n\n  bill Bill @relation(fields: [billId], references: [id])\n}\n\n// 5. Inventory / Stock Management\nmodel StockItem {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  quantity  Decimal  @default(0) @db.Decimal(10, 3)\n  unit      String // kg, pcs, liters\n  threshold Decimal  @default(5) @db.Decimal(10, 3) // Low stock alert level\n  updatedAt DateTime @updatedAt\n}\n\n// 7. Customer Management\nmodel Customer {\n  id          Int      @id @default(autoincrement())\n  name        String\n  phone       String   @unique\n  totalVisits Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  orders Order[]\n}\n\n// 9. Session & Terminal Management\nmodel Session {\n  id         Int     @id @default(autoincrement())\n  userId     Int // Opened by\n  terminalId String?\n\n  openedAt DateTime  @default(now())\n  closedAt DateTime?\n\n  openingCash Decimal  @db.Decimal(10, 2)\n  closingCash Decimal? @db.Decimal(10, 2)\n\n  totalSales Decimal @default(0) @db.Decimal(10, 2)\n  status     String  @default(\"OPEN\") // OPEN, CLOSED\n\n  // Relations\n  user   User    @relation(fields: [userId], references: [id])\n  orders Order[]\n}\n\n// Table Management\nmodel DiningTable {\n  id        Int      @id @default(autoincrement())\n  number    String   @unique\n  capacity  Int      @default(4)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Settings\nmodel Setting {\n  id    Int    @id @default(autoincrement())\n  key   String @unique // e.g., 'tax_rate', 'store_name'\n  value String\n}\n\nenum Status {\n  Pending\n  Cancelled\n  Success\n}\n\nmodel Cart {\n  id         Int      @id @default(autoincrement())\n  userId     Int\n  user       User     @relation(fields: [userId], references: [id])\n  foodId     Int\n  food       Food     @relation(fields: [foodId], references: [id])\n  quantity   Int\n  totalPrice Float\n  status     Status   @default(Pending)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"cart\")\n}\n",
